import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Familiarity y práctica","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/familiarity.md","filePath":"es/guide/characters/familiarity.md"}'),n={name:"es/guide/characters/familiarity.md"};function d(c,a,s,l,o,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="familiarity-practice" tabindex="-1">Familiarity y práctica <a class="header-anchor" href="#familiarity-practice" aria-label="Enlace permanente a &quot;Familiarity y práctica&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Familiarity (fluidez práctica) refleja la soltura con una acción aprendida, sin consumir más límite de habilidades.</li><li>Learned, Practiced y Mastered describen calidad de ejecución, no nuevas habilidades.</li><li>El juego activo puede exigir mantenimiento; la ausencia de calendario no borra conocimientos ni penaliza la fluidez.</li></ul><p><span id="familiarity-and-practice"></span><span id="at-a-glance"></span><span id="maintenance-test"></span><span id="training-and-preparation"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Learned (aprendido)</td><td>La acción sigue siendo conocida aunque haya poca práctica.</td></tr><tr><td>Practiced (practicado)</td><td>La práctica habitual apoya una ejecución normal.</td></tr><tr><td>Mastered (dominado)</td><td>Una ejecución refinada puede mejorar eficiencia, consistencia o tolerancia de tiempos; no garantiza el éxito.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Las Skill Masteries de UO son un sistema de habilidades separado y dependiente de la época.</td><td>Familiarity describe la práctica de acciones aprendidas concretas; no es ese sistema de UO.</td></tr><tr><td>La habilidad general es una medida conocida de competencia.</td><td>Se separa la habilidad general de la fluidez de una acción y de las opciones preparadas para usarla.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/skill-masteries/" target="_blank" rel="noreferrer">UO oficial: Skill Masteries</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un espadachín que regresa conserva las técnicas aprendidas. Durante el juego activo, la fluidez descuidada puede bajar hacia Learned, mientras que la práctica deliberada ayuda a mantenerla.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Las instalaciones de entrenamiento pueden mantener la fluidez de forma eficiente sin sustituir el descubrimiento ni convertirse en la mejor forma de subir la habilidad principal. Las reglas exactas de progreso y mantenimiento siguen abiertas; la preparación marcial y la memoria mágica no comparten una fórmula de capacidad definida.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria de hechizos</a> · <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Ataques especiales</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Familiarity y práctica</a>.</p>',18)])])}const u=e(n,[["render",d]]);export{h as __pageData,u as default};
